// Blink without delay on the Raspberry Pi Pico (arduino-pico core)
const int LED_PIN = 15;
unsigned long last = 0;
bool on = false;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);   // GP25, or the radio's LED on W boards
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(115200);           // USB serial: the baud rate is ignored
}

void loop() {
  unsigned long now = millis();
  if (now - last >= 500) {   // time passed, no waiting
    last = now;
    on = !on;
    digitalWrite(LED_BUILTIN, on ? HIGH : LOW);
    digitalWrite(LED_PIN, on ? HIGH : LOW);
    Serial.print("uptime ms ");
    Serial.println(now);
  }
}
